import assert from 'node:assert/strict';
import {readFileSync} from 'node:fs';
const read=x=>readFileSync(x,'utf8');
const admin=read('app/api/admin/pay/readiness/route.ts');
const ui=read('app/admin/pay/page.tsx');
const pay=read('app/pay/page.tsx');
const a1=read('app/lib/a1topup.ts');
const config=read('app/lib/planapi-config.ts');
const route=read('app/api/process-recharge/route.ts');
const docs=read('docs/ZESHU_PAY_ROLLOUT_2026-11-21.md');
const green=read('app/green/page.tsx');
const storefront=read('app/components/HomeBusinessHub.tsx');
const sitemap=read('app/sitemap.ts');
const home=read('app/page.tsx');

assert(admin.includes('authorizeWhatsAppInboxAdmin(request)'),'Pay configuration must be private to authenticated owner');
assert(admin.includes('inboxNoStore'),'No cached sensitive Pay readiness');
assert(admin.includes('getRuntimeEnvValue'),'Provider configuration comes from server secrets only');
assert(!admin.includes('return env')&&!admin.includes('return values')&&!admin.includes('return entries'),'Never return credential values');
assert(!admin.includes('fetch('),'Readiness must not call chargeable PlanAPI or fulfilment provider APIs');
assert(!admin.includes("export async function POST")&&!admin.includes("export async function PATCH"),'No API for activation or real payments');
assert(admin.includes('codeExecutionReady:false')&&admin.includes('liveTransactionEnabled:false'),'A1topup must remain fail-closed');
assert(admin.includes('providerCallPerformed:false')&&admin.includes('transactionsEnabled:false'),'PlanAPI is only plan/utility discovery');
assert(admin.includes('PLANAPI_CREDENTIALS_ROTATED_CONFIRMED'),'Old credential rotation must be explicitly attested, not guessed');
assert(admin.includes('A1TOPUP_EXECUTION_ENABLED'),'Warn if the execution toggle is requested erroneously');
assert(admin.includes('approvedToGoLive:false'),'No accidental activation');
assert(ui.includes('A1Topup')&&ui.includes('Ezytm · PlanAPI'),'Admin sees both selected partners');
assert(ui.includes('Provider fulfilment')&&ui.includes('OFF'),'Customer money must not be taken for unfinished recharge');
assert(ui.includes('/admin/dashboard'),'Admin can return to headquarters');
assert(pay.includes('Discovery only · No live transactions'),'Public Pay is clearly informational');
assert(route.includes("fulfillment: 'UNAVAILABLE'"),'Recharge API must reject paid fulfilment');
assert(route.includes('{ status: 503 }'),'No silent payment acceptance');
assert(a1.includes("throw new Error('A1TOPUP_POST_BODY_UNVERIFIED')"),'A1Topup cannot execute before provider contract/form verification');
assert(config.includes('PLANAPI_PASSWORD'),'PlanAPI canonical server-only secret variable exists');
assert(docs.includes('Existing owner-selected partner stack'),'Provider decision is documented');
assert(green.includes('Zeshu Green is on hold'),'Green landing page reflects owner pause');
assert(!storefront.includes('action:"green"'),'Green promotions absent');
assert(!home.includes('<GreenOrderImpact'),'Green checkout/order messaging absent');
assert(!sitemap.includes("path:'/green'"),'Paused Green page not SEO-promoted');
console.log('PASS: private Zeshu Pay provider readiness, A1Topup fail-closed, Ezytm discovery, owner-paused Green, no live payments.');
